package stockadjustment

import "time"

// Response is a full stock adjustment (header + its one line) — GET
// /stock-adjustments/{id}. Fields are flattened from the header+item
// join since every document currently has exactly one line — matches
// StockAdjustmentView.vue's flat, non-nested row shape directly.
// SourceStockCountID/SourceStockCountNo (Phase 17) are nil for a
// manually-created adjustment and populated only when this document was
// generated by internal/stockcount's CreateAdjustments — the other half
// of the traceability chain from that package's own
// GeneratedAdjustments (see its doc).
type Response struct {
	ID                 int64      `json:"id,string" example:"1"`
	AdjustmentNo       string     `json:"adjustment_no" example:"ADJ-000001"`
	ProductID          int64      `json:"product_id,string" example:"1"`
	SKU                string     `json:"sku" example:"SKU-0001"`
	ProductName        string     `json:"product_name" example:"Barcode Label Roll"`
	LocationID         int64      `json:"location_id,string" example:"1"`
	LocationCode       string     `json:"location_code" example:"A-01-01"`
	LotNo              string     `json:"lot_no"`
	AdjustType         AdjustType `json:"adjust_type" example:"INCREASE"`
	AdjustQty          float64    `json:"adjust_qty" example:"10"`
	BeforeQty          *float64   `json:"before_qty" example:"120"`
	AfterQty           *float64   `json:"after_qty"`
	Reason             Reason     `json:"reason" example:"Found Goods"`
	Remark             *string    `json:"remark"`
	Status             Status     `json:"status" example:"DRAFT"`
	SourceStockCountID *int64     `json:"source_stock_count_id,string"`
	SourceStockCountNo *string    `json:"source_stock_count_no" example:"CNT-000001"`
	CreatedBy          *int64     `json:"created_by,string"`
	CreatedByName      *string    `json:"created_by_name"`
	CreatedAt          time.Time  `json:"created_at"`
	UpdatedAt          time.Time  `json:"updated_at"`
	ApprovedAt         *time.Time `json:"approved_at"`
	// PendingSince/AgeHours/AgeDays/IsOverdue (Phase 20) are populated
	// only while Status is PENDING — nil/false otherwise, including for
	// DRAFT, APPROVED, and REJECTED. See pendingAging's own doc.
	PendingSince        *time.Time `json:"pending_since"`
	AgeHours            *int       `json:"age_hours"`
	AgeDays             *float64   `json:"age_days"`
	IsOverdue           bool       `json:"is_overdue" example:"false"`
	PendingWarningHours int        `json:"pending_warning_hours" example:"48"`
} //	@name	StockAdjustmentResponse

// ListResponse is one row of GET /stock-adjustments — matches
// StockAdjustmentView.vue's table directly. CreatedBy/CreatedByName and
// the Pending*/Age*/IsOverdue fields (Phase 20) follow the exact same
// shape as Response's own — see its doc.
type ListResponse struct {
	ID            int64      `json:"id,string" example:"1"`
	AdjustmentNo  string     `json:"adjustment_no" example:"ADJ-000001"`
	Date          time.Time  `json:"date"`
	SKU           string     `json:"sku" example:"SKU-0001"`
	ProductName   string     `json:"product_name" example:"Barcode Label Roll"`
	LocationCode  string     `json:"location_code" example:"A-01-01"`
	BeforeQty     *float64   `json:"before_qty" example:"120"`
	AdjustQty     float64    `json:"adjust_qty" example:"10"`
	AdjustType    AdjustType `json:"adjust_type" example:"INCREASE"`
	AfterQty      *float64   `json:"after_qty"`
	Reason        Reason     `json:"reason" example:"Found Goods"`
	Remark        *string    `json:"remark"`
	Status        Status     `json:"status" example:"DRAFT"`
	CreatedBy     *int64     `json:"created_by,string"`
	CreatedByName *string    `json:"created_by_name"`

	PendingSince        *time.Time `json:"pending_since"`
	AgeHours            *int       `json:"age_hours"`
	AgeDays             *float64   `json:"age_days"`
	IsOverdue           bool       `json:"is_overdue" example:"false"`
	PendingWarningHours int        `json:"pending_warning_hours" example:"48"`
} //	@name	StockAdjustmentListResponse

// CreateRequest is POST /stock-adjustments — the drawer's single "Save
// Draft"/"Submit for Approval" click submits the whole (header + one
// line) document at once, mirroring Receiving's own CreateRequest
// shape. Status defaults to DRAFT ("Save Draft"); pass PENDING to
// submit directly ("Submit for Approval").
type CreateRequest struct {
	ProductID  int64      `json:"product_id,string" binding:"required" example:"1"`
	LocationID int64      `json:"location_id,string" binding:"required" example:"1"`
	LotNo      string     `json:"lot_no" example:"LOT-0001"`
	AdjustType AdjustType `json:"adjust_type" binding:"required" example:"INCREASE"`
	AdjustQty  float64    `json:"adjust_qty" binding:"required" example:"10"`
	Reason     Reason     `json:"reason" binding:"required" example:"Found Goods"`
	Remark     *string    `json:"remark"`
	Status     Status     `json:"status" example:"DRAFT"`
	// SourceStockCountID is Phase 17's traceability link — deliberately
	// tagged json:"-" so no client can ever set it via POST
	// /stock-adjustments: it is only ever populated by
	// internal/stockcount's own CreateAdjustments constructing this
	// struct directly in Go before calling CreateTx, never from
	// user-supplied JSON. A manually-created adjustment (the only path
	// that ever binds this struct from a request body) always leaves it
	// nil.
	SourceStockCountID *int64 `json:"-"`
} //	@name	CreateStockAdjustmentRequest

// UpdateRequest is PUT /stock-adjustments/{id} — only allowed while
// still DRAFT (see Status.CanEdit). Also doubles as "Submit for
// Approval" on an existing draft: pass status PENDING to transition it,
// the same dual create-or-submit role CreateRequest's own Status field
// plays for brand new documents.
type UpdateRequest struct {
	LotNo      string     `json:"lot_no" example:"LOT-0001"`
	AdjustType AdjustType `json:"adjust_type" binding:"required" example:"INCREASE"`
	AdjustQty  float64    `json:"adjust_qty" binding:"required" example:"10"`
	Reason     Reason     `json:"reason" binding:"required" example:"Found Goods"`
	Remark     *string    `json:"remark"`
	Status     Status     `json:"status" example:"DRAFT"`
} //	@name	UpdateStockAdjustmentRequest

// ConfirmRequest is POST /stock-adjustments/{id}/confirm — the approval
// action. Action APPROVE calls AddStockTx (INCREASE) or RemoveStockTx
// (DECREASE) atomically in the same transaction; action REJECT performs
// no inventory mutation at all. IdempotencyKey is required — see
// stock_adjustment_confirmations' migration doc for why.
type ConfirmRequest struct {
	IdempotencyKey string `json:"idempotency_key" binding:"required" example:"3fa85f64-5717-4562-b3fc-2c963f66afa6"`
	Action         string `json:"action" binding:"required,oneof=APPROVE REJECT" example:"APPROVE"`
	Remark         string `json:"remark" example:"Confirmed against physical recount"`
} //	@name	ConfirmStockAdjustmentRequest

// SourceCountSummary is one adjustment generated from a specific stock
// count — Phase 17's minimal cross-package shape for
// internal/stockcount's own GeneratedAdjustments lookup. Deliberately
// narrower than Response/ListResponse: stockcount only ever needs to
// display "which documents did this count produce," not this package's
// full detail shape.
type SourceCountSummary struct {
	ID           int64
	AdjustmentNo string
	Status       Status
	Reason       Reason
	CreatedAt    time.Time
}

// ListParams narrows GET /stock-adjustments to the screen's actual
// search box plus type/status/date filters, with pagination.
// Reason/CreatedBy/OlderThanDays/Overdue are Phase 20's additions for
// pending-adjustment follow-up — each independent and combinable with
// the others (matching every existing filter's own AND-together
// design), not a replacement for Status. CreatedBy 0 and OlderThanDays 0
// both mean "not filtered", the same empty-means-unfiltered convention
// Status/Type/Search already use.
type ListParams struct {
	Search        string
	Type          AdjustType
	Status        Status
	Date          *time.Time
	Reason        Reason
	CreatedBy     int64
	OlderThanDays int
	Overdue       bool
	Page          int
	Limit         int
}
